"""Insert into a Binary Search Tree — descend to the empty slot.

Time: O(h)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def insertIntoBST(self, root, val: int):
        if not root:
            return TreeNode(val)
        node = root
        while True:
            if val < node.val:
                if not node.left:
                    node.left = TreeNode(val)
                    return root
                node = node.left
            else:
                if not node.right:
                    node.right = TreeNode(val)
                    return root
                node = node.right
